def transform(grid):
    """Extend diagonal lines of matching non-background cells to the grid edges."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                rr, cc = r + dr, c + dc
                if rr >= h or not (0 <= cc < w):
                    continue
                color = grid[r][c]
                if color == bg or grid[rr][cc] != color:
                    continue

                ar, ac = r - dr, c - dc
                while 0 <= ar < h and 0 <= ac < w and out[ar][ac] == bg:
                    out[ar][ac] = color
                    ar -= dr
                    ac -= dc

                ar, ac = rr + dr, cc + dc
                while 0 <= ar < h and 0 <= ac < w and out[ar][ac] == bg:
                    out[ar][ac] = color
                    ar += dr
                    ac += dc

    return out
